<?php
if (!defined('ABSPATH')) exit;
function drycured_register_recipe_admin_pages(){ add_submenu_page('edit.php?post_type=dry_recipe','Uvoz MD/YAML','Uvoz MD/YAML','manage_options','drycured-md-import','drycured_render_import_page'); }
function drycured_render_import_page(){ if(!current_user_can('manage_options')) return; $result=null; if($_SERVER['REQUEST_METHOD']==='POST'&&check_admin_referer('drycured_import_md')){ $text=''; $src='admin-import'; if(!empty($_FILES['drycured_md_file']['tmp_name'])){ $text=file_get_contents($_FILES['drycured_md_file']['tmp_name']); $src=sanitize_file_name($_FILES['drycured_md_file']['name']); } elseif(!empty($_POST['drycured_md_text'])) $text=wp_unslash($_POST['drycured_md_text']); $result=$text?drycured_import_md_text($text,$src):['error'=>'Nije dostavljena MD datoteka ni tekst.']; } ?>
<div class="wrap"><h1>Uvoz Drycured MD/YAML recepata</h1><p>Učitaj MD datoteku ili zalijepi tekst.</p><?php if($result!==null): ?><div class="notice notice-info"><pre><?php echo esc_html(print_r($result,true)); ?></pre></div><?php endif; ?><form method="post" enctype="multipart/form-data"><?php wp_nonce_field('drycured_import_md'); ?><table class="form-table"><tr><th>MD datoteka</th><td><input type="file" name="drycured_md_file" accept=".md,.txt,.yaml,.yml,.json"></td></tr><tr><th>Ili zalijepi tekst</th><td><textarea name="drycured_md_text" rows="18" style="width:100%;font-family:monospace;"></textarea></td></tr></table><?php submit_button('Uvezi recepte'); ?></form></div><?php }
